fn drain_ready_execution_for_batch(&mut self, execution_batch_size: usize) -> Vec<MahiBlock> {
    let execution_batch_size = execution_batch_size.max(1);
    if execution_batch_size == 1 {
        return self.drain_ready_execution();
    }

    let mut verified = 0_usize;
    for block in &self.pending_execution {
        let status = self
            .verification_status
            .get(&block.block_ref())
            .copied()
            .unwrap_or(MahiBlockVerificationStatus::Pending);
        if status != MahiBlockVerificationStatus::Verified {
            break;
        }
        verified = verified.saturating_add(1);
    }

    let executable = verified - (verified % execution_batch_size);
    let mut ready = Vec::with_capacity(executable);
    for _ in 0..executable {
        if let Some(block) = self.pending_execution.pop_front() {
            ready.push(block);
        }
    }
    ready
}

pub(super) fn reset_mahi_state_after_engine_repair(&self, restart_boundary_round: u64) {
    let Some(network_bootstrap) = self.config.network_bootstrap.as_ref() else {
        return;
    };
    let rebuilt = build_mahi_state(
        self.config.mahi_enabled,
        Some(network_bootstrap),
        parse_mahi_commit_rule(),
        restart_boundary_round,
    );
    if let Ok(mut state_guard) = self.mahi_state.lock() {
        *state_guard = rebuilt;
    }
}

pub(super) fn phase6_inplace_resting_commit_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        std::env::var(PHASE6_INPLACE_RESTING_COMMIT_ENV)
            .map(|value| value != "0" && !value.eq_ignore_ascii_case("false"))
            .unwrap_or(true)
    })
}

pub(super) fn oracle_price_maps_for_mahi_block(
    &self,
    oracle_prices: &[BlockOraclePrice],
) -> (BTreeMap<u64, OraclePrice>, BTreeMap<u64, OraclePrice>) {
    if oracle_prices.is_empty() {
        return (self.market_marks.clone(), self.market_index_prices.clone());
    }
    oracle_price_maps_from_block_observations(oracle_prices)
}

pub(super) fn oracle_price_from_block_value(value: BlockOracleValue) -> Option<OraclePrice> {
    (value.price_ticks > 0 && value.timestamp_ms > 0).then_some(OraclePrice {
        price_ticks: value.price_ticks,
        timestamp_ms: value.timestamp_ms,
    })
}

pub(super) fn insert_newer_oracle_price(
    prices: &mut BTreeMap<u64, OraclePrice>,
    market_id: u64,
    price: OraclePrice,
) {
    let should_insert = prices
        .get(&market_id)
        .is_none_or(|existing| price.timestamp_ms >= existing.timestamp_ms);
    if should_insert {
        prices.insert(market_id, price);
    }
}

pub(crate) fn drain_for_block(
    &mut self,
    timestamp_ms: u64,
    max_items: usize,
    policy_next_nonces: &BTreeMap<u64, u64>,
    inflight_policy_nonces: &BTreeMap<u64, BTreeSet<u64>>,
    excluded_intents: &BTreeSet<IntentId>,
) -> Vec<SignedIntent> {
    if max_items == 0 || self.by_intent.is_empty() {
        return Vec::new();
    }

    let mut selected = Vec::with_capacity(max_items);
    let mut stale = Vec::new();
    let mut last_selected_policy = None;
    let policy_ids = self.rotated_policy_ids();
    let mut expected_nonces = policy_ids
        .iter()
        .map(|policy_id| {
            let mut expected_nonce = policy_next_nonces.get(policy_id).copied().unwrap_or(1);
            if let Some(inflight_nonces) = inflight_policy_nonces.get(policy_id) {
                while inflight_nonces.contains(&expected_nonce) {
                    expected_nonce = expected_nonce.saturating_add(1);
                }
            }
            (*policy_id, expected_nonce)
        })
        .collect::<BTreeMap<_, _>>();
    let mut exhausted = BTreeSet::new();

    while selected.len() < max_items && exhausted.len() < policy_ids.len() {
        let mut made_progress = false;
        for policy_id in policy_ids.iter().copied() {
            if selected.len() >= max_items {
                break;
            }
            if exhausted.contains(&policy_id) {
                continue;
            }
            let Some(expected_nonce) = expected_nonces.get_mut(&policy_id) else {
                exhausted.insert(policy_id);
                continue;
            };

            let next = self.by_policy_nonce.get(&policy_id).and_then(|by_nonce| {
                by_nonce
                    .range(*expected_nonce..)
                    .next()
                    .map(|(nonce, intent_id)| (*nonce, *intent_id))
            });
            let Some((nonce, candidate_intent_id)) = next else {
                exhausted.insert(policy_id);
                continue;
            };
            if nonce > *expected_nonce {
                exhausted.insert(policy_id);
                continue;
            }
            if excluded_intents.contains(&candidate_intent_id) {
                stale.push(candidate_intent_id);
                *expected_nonce = expected_nonce.saturating_add(1);
                made_progress = true;
                continue;
            }
            let Some(candidate) = self.by_intent.get(&candidate_intent_id) else {
                stale.push(candidate_intent_id);
                *expected_nonce = expected_nonce.saturating_add(1);
                made_progress = true;
                continue;
            };
            if intent_expires_at_ms(&candidate.signed_intent.intent) <= timestamp_ms {
                stale.push(candidate_intent_id);
                *expected_nonce = expected_nonce.saturating_add(1);
                made_progress = true;
                continue;
            }

            selected.push(candidate_intent_id);
            *expected_nonce = expected_nonce.saturating_add(1);
            last_selected_policy = Some(policy_id);
            made_progress = true;
        }

        if !made_progress {
            break;
        }
    }

    if let Some(last_selected_policy) = last_selected_policy {
        let next_cursor = policy_ids
            .iter()
            .position(|policy_id| *policy_id == last_selected_policy)
            .map(|index| policy_ids[(index + 1) % policy_ids.len()]);
        self.next_policy_cursor = next_cursor;
    }

    for intent_id in stale {
        if self.remove_intent(&intent_id).is_some() {
            self.dropped_stale_total = self.dropped_stale_total.saturating_add(1);
        }
    }

    let mut drained = Vec::with_capacity(selected.len());
    for intent_id in selected {
        if let Some(intent) = self.remove_intent(&intent_id) {
            self.drained_total = self.drained_total.saturating_add(1);
            drained.push(intent.signed_intent);
        }
    }
    drained
}

fn requeue_execution_front(&mut self, blocks: Vec<MahiBlock>) {
    for block in blocks.into_iter().rev() {
        self.pending_execution.push_front(block);
    }
    self.last_update_at = Some(Instant::now());
}

fn validate_block_restart_boundary(&self, block: &MahiBlock) -> Result<(), String> {
    if block.round < self.restart_boundary_round {
        return Err(format!(
            "mahi block round {} below local restart boundary {}",
            block.round, self.restart_boundary_round
        ));
    }
    if block.round == self.restart_boundary_round {
        if block.ancestors.is_empty() {
            return Ok(());
        }
        return Err(format!(
            "mahi restart-boundary block round {} must not carry ancestors",
            block.round
        ));
    }
    if block
        .ancestors
        .iter()
        .any(|ancestor| ancestor.round < self.restart_boundary_round)
    {
        return Err(format!(
            "mahi block round {} references ancestor below local restart boundary {}",
            block.round, self.restart_boundary_round
        ));
    }
    block
        .validate_ancestor_rules(self.validator_count())
        .map_err(|error| format!("mahi block ancestor rules invalid: {error:?}"))
}

fn prune_committed_intent_wal_replay(inner: &mut PersistedSingleNodeEngineSnapshot) {
    let stale_direct_keys = inner
        .intent_mempool
        .intents_by_order
        .iter()
        .filter_map(|(key, signed_intent)| {
            let committed_next_nonce = inner
                .policy_store
                .next_intent_nonce(signed_intent.intent.policy_id)
                .ok()?;
            (signed_intent.intent.nonce < committed_next_nonce).then_some(*key)
        })
        .collect::<Vec<_>>();
    for key in stale_direct_keys {
        inner.intent_mempool.intents_by_order.remove(&key);
    }
    inner.intent_mempool.known_intents = inner
        .intent_mempool
        .intents_by_order
        .values()
        .map(intent_id)
        .collect();

    let stale_conditional_keys = inner
        .conditional_pool
        .time_after_by_order
        .iter()
        .filter_map(|(key, signed_intent)| {
            let committed_next_nonce = inner
                .policy_store
                .next_intent_nonce(signed_intent.intent.policy_id)
                .ok()?;
            (signed_intent.intent.nonce < committed_next_nonce).then_some(*key)
        })
        .collect::<Vec<_>>();
    for key in stale_conditional_keys {
        inner.conditional_pool.time_after_by_order.remove(&key);
    }

    let mut queued_policy_nonces = BTreeSet::new();
    let duplicate_direct_keys = inner
        .intent_mempool
        .intents_by_order
        .iter()
        .filter_map(|(key, signed_intent)| {
            if key.intent_id != intent_id(signed_intent)
                || key.policy_id != signed_intent.intent.policy_id
                || key.nonce != signed_intent.intent.nonce
            {
                return None;
            }
            let policy_nonce = (signed_intent.intent.policy_id, signed_intent.intent.nonce);
            (!queued_policy_nonces.insert(policy_nonce)).then_some(*key)
        })
        .collect::<Vec<_>>();
    for key in duplicate_direct_keys {
        inner.intent_mempool.intents_by_order.remove(&key);
    }

    let duplicate_conditional_keys = inner
        .conditional_pool
        .time_after_by_order
        .iter()
        .filter_map(|(key, signed_intent)| {
            if key.order_key.intent_id != intent_id(signed_intent)
                || key.order_key.policy_id != signed_intent.intent.policy_id
                || key.order_key.nonce != signed_intent.intent.nonce
            {
                return None;
            }
            let policy_nonce = (signed_intent.intent.policy_id, signed_intent.intent.nonce);
            (!queued_policy_nonces.insert(policy_nonce)).then_some(*key)
        })
        .collect::<Vec<_>>();
    for key in duplicate_conditional_keys {
        inner.conditional_pool.time_after_by_order.remove(&key);
    }

    inner.intent_mempool.known_intents = inner
        .intent_mempool
        .intents_by_order
        .values()
        .map(intent_id)
        .collect();
    inner.conditional_pool.known_intents = inner
        .conditional_pool
        .time_after_by_order
        .values()
        .map(intent_id)
        .collect();
}
